<?php

namespace App\Http\Controllers;

use Exception;
use Throwable;
use App\Models\Order;
use App\Models\ThemeSetting;
use Barryvdh\DomPDF\PDF;
use Illuminate\Support\Facades\Log;
use Smartisan\Settings\Facades\Settings;
use App\Http\Resources\OrderDetailsResource;

/*
 * Public invoice PDF for customers, shared over WhatsApp from the POS receipt.
 * The route is protected by a signed URL, so only links generated by the POS
 * work and order ids can't be guessed.
 */
class InvoiceController extends Controller
{
    // 80mm receipt width in points.
    private const PAPER_WIDTH = 226.77;
    // Largest page height PDF allows (200 inches), used for the measuring pass.
    private const MAX_PAPER_HEIGHT = 14400;
    // Logo box in the receipt header, in points.
    private const LOGO_MAX_WIDTH  = 150;
    private const LOGO_MAX_HEIGHT = 100;

    public function show(Order $order): mixed
    {
        try {
            $pdf = $this->receiptPdf([
                'invoice' => json_decode(json_encode(new OrderDetailsResource($order)), true),
                'company' => Settings::group('company')->all(),
                'logo'    => $this->pdfLogo(),
            ]);

            return $pdf->stream('invoice-' . $order->order_serial_no . '.pdf');
        } catch (Exception $exception) {
            Log::info($exception->getMessage());
            abort(404);
        }
    }

    /*
     * The receipt logo for the printed POS receipts, served from our own domain
     * so the receipt snapshot sent over WhatsApp can include it.
     */
    public function logo(): mixed
    {
        $png = $this->receiptLogoPng();
        if ($png === null) {
            abort(404);
        }

        return response($png, 200, [
            'Content-Type'  => 'image/png',
            'Cache-Control' => 'public, max-age=86400',
        ]);
    }

    private function pdfLogo(): ?array
    {
        $png = $this->receiptLogoPng();
        if ($png === null) {
            return null;
        }

        [$width, $height] = getimagesizefromstring($png);
        $scale = min(self::LOGO_MAX_WIDTH / $width, self::LOGO_MAX_HEIGHT / $height);

        return [
            'src'    => 'data:image/png;base64,' . base64_encode($png),
            'width'  => round($width * $scale, 2),
            'height' => round($height * $scale, 2),
        ];
    }

    /*
     * The site logo (Settings > Theme) as a PNG with its empty margin cut off:
     * uploaded logos often sit small in the middle of a square canvas, which
     * makes them tiny once fitted into the receipt header. The result is cached
     * per source file, and the receipt just goes without a logo if it can't be read.
     */
    private function receiptLogoPng(): ?string
    {
        try {
            $media = ThemeSetting::where('key', 'theme_logo')->first()?->getMedia('theme-logo')->last();
            // The original upload is sharpest; the resized WebP and the default
            // theme logo are fallbacks.
            foreach ([$media?->getPath(), $media?->getPath('logo'), public_path('images/theme/theme-logo.png')] as $path) {
                if (!$path || !is_file($path)) {
                    continue;
                }

                $cache = storage_path('app/receipt-logo/' . md5($path . filemtime($path)) . '.png');
                if (is_file($cache)) {
                    return file_get_contents($cache);
                }

                $image = @imagecreatefromstring(file_get_contents($path));
                if (!$image) {
                    continue;
                }

                $png = $this->trimmedPng($image);
                if (!is_dir(dirname($cache))) {
                    mkdir(dirname($cache), 0755, true);
                }
                file_put_contents($cache, $png);

                return $png;
            }
        } catch (Throwable $throwable) {
            Log::info($throwable->getMessage());
        }

        return null;
    }

    // Crops away transparent and near-white margins around the logo drawing.
    private function trimmedPng(\GdImage $image): string
    {
        imagepalettetotruecolor($image);
        $width  = imagesx($image);
        $height = imagesy($image);

        $minX = $width;
        $minY = $height;
        $maxX = -1;
        $maxY = -1;
        for ($y = 0; $y < $height; $y++) {
            for ($x = 0; $x < $width; $x++) {
                $color = imagecolorat($image, $x, $y);
                $alpha = ($color >> 24) & 0x7F; // 0 = opaque, 127 = transparent
                $white = (($color >> 16) & 0xFF) > 245 && (($color >> 8) & 0xFF) > 245 && ($color & 0xFF) > 245;
                if ($alpha < 100 && !$white) {
                    $minX = min($minX, $x);
                    $maxX = max($maxX, $x);
                    $minY = min($minY, $y);
                    $maxY = max($maxY, $y);
                }
            }
        }

        if ($maxX >= $minX && $maxY >= $minY) {
            $cropped = imagecreatetruecolor($maxX - $minX + 1, $maxY - $minY + 1);
            imagealphablending($cropped, false);
            imagecopy($cropped, $image, 0, 0, $minX, $minY, $maxX - $minX + 1, $maxY - $minY + 1);
            $image = $cropped;
        }

        imagesavealpha($image, true);
        ob_start();
        imagepng($image);

        return ob_get_clean();
    }

    private function receiptPdf(array $data): PDF
    {
        // A receipt is one continuous slip, so render once on a very tall page to
        // measure the content, then render again on a page cut to that height.
        $height  = 0;
        $measure = app('dompdf.wrapper')->loadView('pdf.pos_invoice', $data)
            ->setPaper([0, 0, self::PAPER_WIDTH, self::MAX_PAPER_HEIGHT]);
        $measure->getDomPDF()->setCallbacks([[
            'event' => 'end_frame',
            'f'     => function ($frame) use (&$height) {
                if ($frame->get_node()->nodeName === 'body') {
                    $height = $frame->get_position('y') + $frame->get_margin_height();
                }
            },
        ]]);
        $measure->render();

        // Font subsetting keeps the file small for customers opening it on mobile data.
        return app('dompdf.wrapper')->loadView('pdf.pos_invoice', $data)
            ->setOption('isFontSubsettingEnabled', true)
            ->setPaper([0, 0, self::PAPER_WIDTH, min(max($height, 200), self::MAX_PAPER_HEIGHT)]);
    }
}
